import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = data[1:1 + n]
    m = int(data[1 + n])
    b = data[2 + n:2 + n + m]
    adj = {}
    indeg = {}
    for v in a + b:
        if v not in adj:
            adj[v] = []
            indeg[v] = 0
    for arr in (a, b):
        for i in range(len(arr) - 1):
            adj[arr[i]].append(arr[i + 1])
            indeg[arr[i + 1]] += 1
    q = deque(v for v in adj if indeg[v] == 0)
    seen = 0
    while q:
        v = q.popleft()
        seen += 1
        for w in adj[v]:
            indeg[w] -= 1
            if indeg[w] == 0:
                q.append(w)
    print('true' if seen == len(adj) else 'false')

